 const cards=rs.map(r=>{const key=r[0],d=s.regionData[key]||(s.regionData[key]={policy:"balanced",level:1,prosperity:50}),has=own(r),known=discovered(key),canExplore=!has&&!known&&adjacent(key)&&s.level>=Math.max(2,r[4]-2)&&(Number(s.inventory.scouts)||0)>=1&&(s.bread+s.wheat)>=20,open=has||(known&&s.level>=r[4]&&s.coins>=r[5]&&s.wood>=r[6]&&s.stone>=r[7]&&(key!=="river"||count("shipyard")>0)),g=Number(s.garrisons[key])||0,route=s.tradeRoutes.includes(key);return '<article class="empire-card empire-province-card '+(has?"owned":"locked")+'"><div class="empire-province-top"><span>'+r[2]+'</span><span class="empire-province-state">'+(has?"EIGENES GEBIET":known?"ERKUNDET":canExplore?"ERKUNDUNG MÖGLICH":"UNBEKANNT")+'</span></div><h3>'+r[1]+'</h3><p>'+r[3]+'</p><small>Ab Stufe '+r[4]+' · Garnison '+g+'</small>'+(has?'<div class="empire-province-stats"><span>Wohlstand <b>'+Math.round(d.prosperity)+'/100</b></span><span>Stufe <b>'+d.level+'</b></span><span>Route <b>'+(route?"aktiv":"inaktiv")+'</b></span></div><label class="empire-province-label">Schwerpunkt<select data-region-policy="'+key+'">'+pol.map(p=>'<option value="'+p[0]+'" '+(d.policy===p[0]?"selected":"")+'>'+p[1]+'</option>').join("")+'</select></label><div class="empire-province-actions"><button class="empire-btn" data-action="governor" data-id="'+key+'">'+(s.governors[key]?"✓ Statthalter eingesetzt":"Statthalter · 15 Wissen")+'</button><button class="empire-btn secondary" data-action="route" data-id="'+key+'" '+(!count("market")?"disabled":"")+'>'+(route?"Route beenden":"Handelsroute · 25 Holz + 5 Bauholz")+'</button><button class="empire-btn secondary" data-action="deploy" data-id="'+key+'" '+(s.units<5?"disabled":"")+'>'+g+' Garnison · 5 stationieren</button><button class="empire-btn secondary" data-action="recall" data-id="'+key+'" '+(g<1?"disabled":"")+'>'+(g?"Garnison zurückrufen":"Keine Garnison")+'</button></div>':known?'<small>Benötigt '+r[5]+' Coins · '+r[6]+' Holz · '+r[7]+' Stein</small><button class="empire-btn" data-action="region" data-id="'+rs.indexOf(r)+'" '+(!open?"disabled":"")+'>'+(open?"Provinz erschließen":"Voraussetzungen fehlen")+'</button>':'<p class="empire-muted">Noch nicht kartiert. Erkundung benötigt 1 Kundschafter und 20 Nahrung sowie Rathausstufe '+Math.max(2,r[4]-2)+'.</p><button class="empire-btn" data-action="explore-region" data-id="'+key+'" '+(!canExplore?"disabled":"")+'>'+(canExplore?"Gebiet erkunden":"Noch nicht erreichbar")+'</button>')+'</article>'}).join("");
