 const here=s.worldArmyPosition==="capital"?"Aurelion":(rs.find(r=>r[0]===s.worldArmyPosition)?.[1]||"Aurelion"),latest=(s.aiEvents||[]).slice(0,3).map(e=>'<p><b>'+esc(e.name)+'</b> '+esc(e.text)+'. <small>'+esc(e.day)+'</small></p>').join("");
