if(act==="court-drama"){const q=s.court,e=q.activeDrama;if(!e)return;if(e.id==="merchant"){if(id==="grant"){s.coins+=180;s.intrigue.guilds=Math.min(100,s.intrigue.guilds+12);s.intrigue.commons=Math.max(0,s.intrigue.commons-8)}else if(id==="deny"){s.intrigue.guilds=Math.max(0,s.intrigue.guilds-12);s.intrigue.commons=Math.min(100,s.intrigue.commons+8);s.mood=Math.min(100,s.mood+2)}else{s.coins=Math.max(0,s.coins-60);s.intrigue.guilds=Math.min(100,s.intrigue.guilds+5);s.intrigue.nobles=Math.min(100,s.intrigue.nobles+3)}}else if(e.id==="envoy"){if(id==="accept"){s.relations.vale=Math.min(100,(s.relations.vale||0)+18);s.intrigue.legitimacy=Math.max(0,s.intrigue.legitimacy-6)}else if(id==="reject"){s.intrigue.legitimacy=Math.min(100,s.intrigue.legitimacy+5);s.relations.vale=Math.max(0,(s.relations.vale||0)-8)}else{s.knowledge+=12;s.relations.vale=Math.min(100,(s.relations.vale||0)+3)}}else{if(id==="publish"){s.intrigue.legitimacy=Math.min(100,s.intrigue.legitimacy+10);s.intrigue.nobles=Math.max(0,s.intrigue.nobles-8)}else if(id==="seal"){s.intrigue.nobles=Math.min(100,s.intrigue.nobles+8);s.intrigue.legitimacy=Math.max(0,s.intrigue.legitimacy-4)}else{s.knowledge+=20;q.plotStage=Math.min(3,q.plotStage+1)}}q.activeDrama=null;s.eventLog=(s.eventLog||[]).concat("Hofentscheidung: "+e.title+" – "+id).slice(-15);save();note("Deine Entscheidung hat das Machtgefüge verändert.");return}

