const pathSteps=[
 {name:"Aurelion gründen",desc:"Lerne die Grundlagen: sichere Nahrung und Holzversorgung.",goal:"Baue ein zusätzliches Feld und ein Holzfällerlager.",tab:"build",unlock:"Hauptstadt, Bauen und Startwirtschaft"},
 {name:"Die Siedlung versorgen",desc:"Sichere Baumaterialien und verbessere die Lagerung.",goal:"Errichte einen Steinbruch und einen Speicher.",tab:"build",unlock:"Stadtverwaltung und Außenstädte"},
 {name:"Brot und Wissen",desc:"Baue eine Produktionskette und beginne mit Forschung.",goal:"Errichte Windmühle und Bäckerei und erforsche Backkunst.",tab:"research",unlock:"Forschung und weiterführende Stadtentwicklung"},
 {name:"Die Nachbarn kennenlernen",desc:"Öffne Handel und stelle eine erste Verteidigung auf.",goal:"Baue Marktplatz und Kaserne und stelle 10 Krieger auf.",tab:"diplomacy",unlock:"Handel, Diplomatie und Militär"},
 {name:"Eisen und neue Gebiete",desc:"Erschließe neue Rohstoffe und erkunde die Welt.",goal:"Baue Eisenerzmine und Schmelzhütte.",tab:"world",unlock:"Weltkarte, Provinzen und Reichsverwaltung"},
 {name:"Die Flussmark",desc:"Bereite eine Expansion über den Fluss vor.",goal:"Erreiche Rathausstufe 4, baue eine Werft und erschließe die Flussmark.",tab:"world",unlock:"Provinzverwaltung und größere Expansion"},
 {name:"Ein Reich entsteht",desc:"Vereine Städte, Forschung und Diplomatie zu einem Reich.",goal:"Erreiche Rathausstufe 7 und errichte den Königspalast.",tab:"strategy",unlock:"Späte Reichsentwicklung und Königspalast"}
];
const tabChapter={overview:0,path:0,handbook:0,story:0,quests:0,achievements:0,events:0,map:0,build:0,shop:0,inventory:0,city:0,economy:1,cities:1,research:2,trade:3,diplomacy:3,military:3,intrigue:3,court:3,world:4,strategy:4,council:5};
